import{_ as r,o as e,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Dashboard for Ceph Developer Summit - Vampire","description":"","frontmatter":{"title":"Dashboard for Ceph Developer Summit - Vampire","date":"2026-08-14T00:00:00.000Z","updated":"2026-08-15T00:00:00.000Z","tags":["Ceph","Dashboard","CephFS","RGW","会议纪要"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Dashboard_for_Ceph_Developer_Summit_-_Vampire.md","filePath":"posts/2026/Dashboard_for_Ceph_Developer_Summit_-_Vampire.md","lastUpdated":null}'),i={name:"posts/2026/Dashboard_for_Ceph_Developer_Summit_-_Vampire.md"};function s(l,a,n,d,h,p){return e(),t("div",null,[...a[0]||(a[0]=[o('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次会议是 Ceph Developer Summit Vampire 版本的 Dashboard 专题讨论，由 Dashboard 组件负责人 Afreen（中途接替代班主持人 Tom）主持，团队成员共同讨论了 Vampire 版本中 Dashboard 的多项新特性、功能增强与维护事项。</p><h2 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h2><h3 id="_1-集中式日志-centralized-logging" tabindex="-1">1. 集中式日志（Centralized Logging） <a class="header-anchor" href="#_1-集中式日志-centralized-logging" aria-label="Permalink to &quot;1. 集中式日志（Centralized Logging）&quot;">​</a></h3><p>当前 Dashboard 已集成 Loki + Alloy（原 Promtail）日志栈，但现有实现为 iframe 内嵌 Grafana UI，存在以下问题：</p><ul><li>用户需要在 iframe 内单独登录 Grafana，体验割裂</li><li>界面不美观，加载缓慢</li></ul><p><strong>目标方案：</strong></p><ul><li>移除 iframe 集成，直接调用 Loki API</li><li>将集群日志（cluster logs）与审计日志（audit logs）合并为统一视图</li><li>在 Dashboard 中展示 MGR 及所有客户端日志</li><li>提供日志轮转（log rotation）配置的友好 UX</li></ul><p><strong>讨论亮点（Ankush）：</strong> 希望用户能从告警（alerts）直接跳转到对应资源（OSD、MON、RGW），并在 Dashboard 内完成调试，而无需切换到外部工具。</p><h3 id="_2-s3-对象管理浏览器-s3-object-browser" tabindex="-1">2. S3 对象管理浏览器（S3 Object Browser） <a class="header-anchor" href="#_2-s3-对象管理浏览器-s3-object-browser" aria-label="Permalink to &quot;2. S3 对象管理浏览器（S3 Object Browser）&quot;">​</a></h3><p>当前 Dashboard 中 RGW 管理仅支持 bucket 管理，缺少对象级别的操作界面。</p><p><strong>目标：</strong> 为管理员提供对象管理视图，支持对象列表、上传、下载操作。</p><p><strong>技术实现（Naman）：</strong></p><ul><li>设计文档正在评审中</li><li>基于现有 RGW Admin Ops API 实现</li><li>使用 Carbon Design System 构建 UI</li><li>关键挑战：大规模 bucket（如百万级对象）下的分页（pagination）处理 <ul><li>RGW Admin Ops API 已支持分页，Dashboard API 层及表格组件也支持，实现相对顺畅</li></ul></li></ul><h3 id="_3-概览页面增强-overview-page-improvements-grafana-overview-pages" tabindex="-1">3. 概览页面增强（Overview Page Improvements / Grafana Overview Pages） <a class="header-anchor" href="#_3-概览页面增强-overview-page-improvements-grafana-overview-pages" aria-label="Permalink to &quot;3. 概览页面增强（Overview Page Improvements / Grafana Overview Pages）&quot;">​</a></h3><p><strong>核心理念（Ankush）：</strong> 构建层次化（hierarchical）的下钻（drill-down）模型：</p><ul><li>从集群总览（cluster overview）出发，逐层下钻到 block / file / object 存储类型</li><li>每层统一展示：存储容量、健康状态、IO 吞吐、延迟（P99、P95、中位数）、镜像/复制状态</li><li>进一步可下钻到 top 5 使用量最高的 image、volume、bucket 等</li></ul><p><strong>目标：</strong> 以 Carbon 原生图表替代 Grafana iframe 嵌入，提升加载速度，实现日志、告警、监控的一体化体验，避免在 Grafana、Prometheus、Loki 之间反复切换。</p><p><strong>待确认事项：</strong> 需要盘点各组件是否已有所需 metrics，对于镜像等功能需与对应团队协调。</p><h3 id="_4-stretch-cluster-管理" tabindex="-1">4. Stretch Cluster 管理 <a class="header-anchor" href="#_4-stretch-cluster-管理" aria-label="Permalink to &quot;4. Stretch Cluster 管理&quot;">​</a></h3><p>Stretch cluster 为引导（bootstrap）阶段配置，现有集群不建议从普通模式切换为 stretch 模式。</p><p><strong>Dashboard 目标：</strong></p><ul><li>区分普通集群与 stretch 集群的展示</li><li>Pool 表单已支持 stretch cluster 模式配置（Abhishek 已完成相关工作）</li><li>待 Cephadm 侧 bootstrap 支持完善后跟进 Dashboard 实现</li></ul><h3 id="_5-cephfs-mirroring" tabindex="-1">5. CephFS Mirroring <a class="header-anchor" href="#_5-cephfs-mirroring" aria-label="Permalink to &quot;5. CephFS Mirroring&quot;">​</a></h3><p><strong>进展：</strong> 已有 PR 提交，第一个端到端流程代码即将合并进 main 分支。</p><p><strong>功能目标（Pedro）：</strong></p><ul><li>用户可在 Dashboard 内管理 snapshot，并通过 UI 触发跨集群数据复制</li><li>后续加入监控工具，管理员可同时管理和监控整个 CephFS 镜像流程</li></ul><p><strong>讨论点（Ankush）：</strong> 建议加入镜像日志，以便调试镜像失败场景；同时提议展示数据从 Site A 到 Site B 的传输进度、增量大小、耗时等信息。</p><p>Pedro 确认监控功能将作为第二阶段交付，计划在 Vampire 版本结束前完成。</p><h3 id="_6-可扩展性与性能-scalability" tabindex="-1">6. 可扩展性与性能（Scalability） <a class="header-anchor" href="#_6-可扩展性与性能-scalability" aria-label="Permalink to &quot;6. 可扩展性与性能（Scalability）&quot;">​</a></h3><p><strong>计划方向：</strong></p><ul><li>在 CI 中加入性能与可扩展性测试，检测 JS/CSS bundle 大小变化</li><li>为 Dashboard 概览页等核心页面建立性能基准（benchmark）</li><li>验证 Gzip 压缩对 JavaScript/text MIME 类型已正确启用（此前曾有 bug 影响加载性能）</li><li>规模测试目前难以在 CI 中自动化，计划每个版本发布前进行一次手动规模测试，利用上游实验室资源</li></ul><h3 id="_7-资源详情页-resource-pages" tabindex="-1">7. 资源详情页（Resource Pages） <a class="header-anchor" href="#_7-资源详情页-resource-pages" aria-label="Permalink to &quot;7. 资源详情页（Resource Pages）&quot;">​</a></h3><p><strong>背景：</strong> 当前各资源（OSD、pool、host 等）详情通过嵌套表格展示，层次过深，可读性差。</p><p><strong>目标：</strong> 为每类资源创建独立的详情页（dedicated resource pages），展示数据保护配置、性能指标、缓存层配置等完整信息。</p><p><strong>进展：</strong> 已于 5 月开始开发，pool 详情页已完成，OSD、host 等页面持续推进。GSoC 2026 参与者 Ali 贡献了大量代码，值得肯定。</p><h3 id="_8-erasure-coding-ec-增强" tabindex="-1">8. Erasure Coding（EC）增强 <a class="header-anchor" href="#_8-erasure-coding-ec-增强" aria-label="Permalink to &quot;8. Erasure Coding（EC）增强&quot;">​</a></h3><p><strong>目标：</strong></p><ul><li>修复 pool 表单中 EC profile 创建流程的已知 bug</li><li>改善 form-in-form 的嵌套 UX 问题</li><li>修正错误的 EC 容量计算</li><li>对高级参数进行合理隐藏，简化用户操作</li><li>更直观地展示 K+M 参数含义及存储节省比例</li></ul><p><strong>背景（Ankush）：</strong> Ceph 社区正在积极推广 EC 替代复制（replication）存储，EC 性能近年来持续改进，Dashboard 需跟进支持。</p><h3 id="_9-nfs-增强" tabindex="-1">9. NFS 增强 <a class="header-anchor" href="#_9-nfs-增强" aria-label="Permalink to &quot;9. NFS 增强&quot;">​</a></h3><p><strong>问题：</strong> NFS cluster 创建功能目前不在 Dashboard 中，相关上游 PR 因后端问题长期未合并，部分 NFS 测试被临时禁用。</p><p><strong>目标：</strong></p><ul><li>合并积压 PR，恢复并扩展 NFS 测试</li><li>支持 NFS cluster 创建（与 SMB cluster 创建流程统一，两者约 80%-90% 工作流相同）</li><li>合并 rate limiting 相关 PR</li></ul><p><strong>进展：</strong> 后端阻塞问题已由 Shweta 团队确认解决，Dashboard 侧 PR 可跟进 rebase 合并。</p><h3 id="_10-遥测-telemetry" tabindex="-1">10. 遥测（Telemetry） <a class="header-anchor" href="#_10-遥测-telemetry" aria-label="Permalink to &quot;10. 遥测（Telemetry）&quot;">​</a></h3><p><strong>目标（Anurag）：</strong> 收集 Dashboard 功能使用情况的聚合 metrics，纳入现有 Ceph telemetry 报告，帮助维护者了解功能采用率与配置情况，指导后续开发方向。计划新增约 10 项 Dashboard telemetry 指标。</p><h3 id="_11-rbd-mirroring-统一" tabindex="-1">11. RBD Mirroring 统一 <a class="header-anchor" href="#_11-rbd-mirroring-统一" aria-label="Permalink to &quot;11. RBD Mirroring 统一&quot;">​</a></h3><p><strong>目标：</strong> 将 RBD mirroring 页面的 UX 与正在开发的新版 CephFS mirroring 设计对齐，统一两者风格。</p><p><strong>节奏：</strong> 作为 stretch goal，可视 CephFS mirroring 完成情况决定是否在 Vampire 内完成，或推迟至后续版本。</p><h3 id="_12-pool-snapshots" tabindex="-1">12. Pool Snapshots <a class="header-anchor" href="#_12-pool-snapshots" aria-label="Permalink to &quot;12. Pool Snapshots&quot;">​</a></h3><p>简要讨论后，Nizam 表示池级别快照实际使用场景较少，价值有限，建议进一步评估实际需求后再决定是否实现。</p><h3 id="_13-nvme-of-ha" tabindex="-1">13. NVMe-oF HA <a class="header-anchor" href="#_13-nvme-of-ha" aria-label="Permalink to &quot;13. NVMe-oF HA&quot;">​</a></h3><p><strong>背景：</strong> 上游正在讨论将 NVMe-oF 相关 API 从 Dashboard 迁移到独立的 NVMeOF 模块（由 Kifu 主导）。</p><p><strong>结论：</strong> HA 逻辑将由 NVMeOF 模块自身处理，Dashboard 侧无需单独实现 HA，后续跟进模块接口对接即可。</p><h3 id="_14-一键升级与滚动升级-upgrades" tabindex="-1">14. 一键升级与滚动升级（Upgrades） <a class="header-anchor" href="#_14-一键升级与滚动升级-upgrades" aria-label="Permalink to &quot;14. 一键升级与滚动升级（Upgrades）&quot;">​</a></h3><p>功能高度依赖 Ceph 上游实现，需与上游团队进一步讨论方案细节，待后续版本规划。</p><h3 id="_15-smb-on-rgw" tabindex="-1">15. SMB on RGW <a class="header-anchor" href="#_15-smb-on-rgw" aria-label="Permalink to &quot;15. SMB on RGW&quot;">​</a></h3><p><strong>背景（Nizam）：</strong> SMB 新增了对 RGW bucket 的支持（类似 NFS share on bucket），相关 PR 已合并进 main。</p><p><strong>下一步：</strong> 需与后端团队确认功能稳定性，评估是否在 Vampire 版本中同步实现 Dashboard 支持。</p><h3 id="_16-dashboard-更名为-ceph-console" tabindex="-1">16. Dashboard 更名为 Ceph Console <a class="header-anchor" href="#_16-dashboard-更名为-ceph-console" aria-label="Permalink to &quot;16. Dashboard 更名为 Ceph Console&quot;">​</a></h3><p>正在内部讨论将 &quot;Ceph Dashboard&quot; 更名为 &quot;Ceph Console&quot;，但涉及范围较大（全局重命名），尚未最终确定，可能推迟至后续版本。</p><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事项</th><th>负责人</th><th>状态</th></tr></thead><tbody><tr><td>集中式日志 UI 设计</td><td>David Guy（设计），团队跟进实现</td><td>设计进行中</td></tr><tr><td>S3 对象管理设计评审</td><td>Naman</td><td>设计评审中</td></tr><tr><td>概览页 metrics 盘点与跨团队协调</td><td>Nizam / Ankush</td><td>待启动</td></tr><tr><td>CephFS Mirroring 第一个端到端 PR 合并</td><td>Pedro</td><td>即将合并</td></tr><tr><td>NFS PR rebase 与合并</td><td>Nizam</td><td>跟进中</td></tr><tr><td>EC Pool 表单 bug 修复</td><td>Abhishek / Devika</td><td>进行中</td></tr><tr><td>资源详情页（OSD、host 等）</td><td>Ali（GSoC）及团队</td><td>进行中</td></tr><tr><td>Telemetry 指标文档与实现</td><td>Anurag</td><td>进行中</td></tr><tr><td>NVMeOF 模块接口对接</td><td>Nizam，与上游协调</td><td>待跟进</td></tr><tr><td>通知持久化方案讨论</td><td>Ernesto / Nizam / Ganesh</td><td>待讨论</td></tr><tr><td>Dashboard 更名评估</td><td>全团队</td><td>讨论中</td></tr></tbody></table><h2 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h2><p>Afreen（主持）、Tom（代班主持）、Nizam、Ankush、Sagar、Naman、Pedro、Abhishek、Anurag、Divya、Ganesh、Adam 等。</p>',66)])])}const m=r(i,[["render",s]]);export{g as __pageData,m as default};
